  ('1', NULL, NULL, '0.0001', '1234567.8912'),
  ('2', '1', '300000.0000', '-5.5000', '0.0000'),
  ('3', '1', NULL, '1.0000', '1.0000');
INSERT INTO sales.sales_territory ("TerritoryID", "Name", "Group") VALUES
  ('1', 'Northwest', 'North America');
CREATE TEMP TABLE pp_actual ON COMMIT DROP AS
SELECT * FROM sales.v_sales_person;
DO $pp$
DECLARE got text[];
BEGIN
  SELECT array_agg(attname::text ORDER BY attnum) INTO got FROM pg_attribute WHERE attrelid = 'pp_actual'::regclass AND attnum > 0 AND NOT attisdropped;
  IF got IS DISTINCT FROM ARRAY['BusinessEntityID', 'Title', 'FirstName', 'MiddleName', 'LastName', 'Suffix', 'JobTitle', 'PhoneNumber', 'PhoneNumberType', 'EmailAddress', 'EmailPromotion', 'AddressLine1', 'AddressLine2', 'City', 'StateProvinceName', 'PostalCode', 'CountryRegionName', 'TerritoryName', 'TerritoryGroup', 'SalesQuota', 'SalesYTD', 'SalesLastYear']::text[] THEN
    RAISE EXCEPTION 'agreed test failed (%): columns are %, expected %', 'test 01 no territory, two phones, no email; trailing space kept; a sales person without an address is dropped', got, ARRAY['BusinessEntityID', 'Title', 'FirstName', 'MiddleName', 'LastName', 'Suffix', 'JobTitle', 'PhoneNumber', 'PhoneNumberType', 'EmailAddress', 'EmailPromotion', 'AddressLine1', 'AddressLine2', 'City', 'StateProvinceName', 'PostalCode', 'CountryRegionName', 'TerritoryName', 'TerritoryGroup', 'SalesQuota', 'SalesYTD', 'SalesLastYear']::text[];
  END IF;
END $pp$;
CREATE TEMP TABLE pp_expected (LIKE pp_actual) ON COMMIT DROP;
INSERT INTO pp_expected VALUES
  ('1', NULL, 'First1', NULL, 'Last1', NULL, 'Sales Representative', '555-0100', 'Cell', NULL, '0', '1 Main St', NULL, 'Bothell', 'Washington', '98011', 'United States', NULL, NULL, NULL, '0.0001', '1234567.8912'),
  ('1', NULL, 'First1', NULL, 'Last1', NULL, 'Sales Representative', '555-0199', NULL, NULL, '0', '1 Main St', NULL, 'Bothell', 'Washington', '98011', 'United States', NULL, NULL, NULL, '0.0001', '1234567.8912'),
  ('2', 'Ms.', 'Ann ', NULL, 'Last2', 'Jr.', 'Sales Representative', NULL, NULL, 'ann@example.com', '2', '2 High St', 'Suite 5', 'Seattle', 'Washington', '98104', 'United States', 'Northwest', 'North America', '300000', '-5.5', '0');
DO $pp$
DECLARE missing bigint; extra bigint;
BEGIN
  SELECT count(*) INTO missing FROM ((SELECT * FROM pp_expected) EXCEPT ALL (SELECT * FROM pp_actual)) AS d;
  SELECT count(*) INTO extra FROM ((SELECT * FROM pp_actual) EXCEPT ALL (SELECT * FROM pp_expected)) AS d;
  IF missing > 0 OR extra > 0 THEN
    RAISE EXCEPTION 'agreed test failed (%): % expected row(s) missing, % unexpected row(s) in the result', 'test 01 no territory, two phones, no email; trailing space kept; a sales person without an address is dropped', missing, extra;
  END IF;
END $pp$;
ROLLBACK;
